package com.example.g.media;
import android.content.Context;import android.net.Uri;import androidx.documentfile.provider.DocumentFile;import com.example.g.models.MediaItem;import java.io.*;import java.util.List;
public final class BatchFileOperations{private BatchFileOperations(){}public interface Callback{void done(int copied,Exception error);}public static void copyToTree(Context c,List<MediaItem> items,Uri tree,Callback callback){new Thread(()->{int count=0;Exception failure=null;try{DocumentFile folder=DocumentFile.fromTreeUri(c,tree);if(folder==null||!folder.canWrite())throw new IOException("Selected folder is not writable");for(MediaItem item:items){String mime=item.mime==null?"application/octet-stream":item.mime;DocumentFile output=folder.createFile(mime,item.name==null?"media_"+System.currentTimeMillis():item.name);if(output==null)throw new IOException("Could not create "+item.name);try(InputStream in=c.getContentResolver().openInputStream(item.uri);OutputStream out=c.getContentResolver().openOutputStream(output.getUri())){if(in==null||out==null)throw new IOException("Could not copy "+item.name);byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);}count++;}}catch(Exception e){failure=e;}int result=count;Exception error=failure;new android.os.Handler(android.os.Looper.getMainLooper()).post(()->callback.done(result,error));}).start();}}
